use std::{env, error::Error, fs};

use ga_domain::event_schema::validate_custom_schema;
use serde_json::Value;

#[test]
#[ignore = "requires the synthetic fixture generated by the pinned Python schema validator"]
fn matches_the_bounded_python_custom_schema_profile() -> Result<(), Box<dyn Error>> {
    let examples: Vec<(Value, bool)> =
        serde_json::from_slice(&fs::read(env::var("GA_TEST_CUSTOM_SCHEMAS")?)?)?;
    for (index, (schema, valid)) in examples.into_iter().enumerate() {
        let result = validate_custom_schema(&schema);
        assert_eq!(result.is_ok(), valid, "schema {index}: {result:?}");
    }
    Ok(())
}
